def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate the straight separator of a color distinct from the panel colors.
    for c in range(w):
        vals = {grid[r][c] for r in range(h)}
        if len(vals) == 1 and next(iter(vals)) not in (0, 1, 2, 5):
            left = [row[:c] for row in grid]
            right = [row[c + 1:] for row in grid]
            n = min(len(left[0]), len(right[0]))
            return [[3 if left[r][j] == 5 and right[r][j] == 5 else 5
                     for j in range(n)] for r in range(h)]

    for r in range(h):
        vals = set(grid[r])
        if len(vals) == 1 and grid[r][0] not in (0, 1, 2, 5):
            top, bottom = grid[:r], grid[r + 1:]
            n = min(len(top), len(bottom))
            return [[3 if top[i][c] == 5 and bottom[i][c] == 5 else 5
                     for c in range(w)] for i in range(n)]

    return grid
